// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address sender) public {
        amount = bound(amount, 1, 1 ether);
        vm.assume(sender != address(0));

        vm.deal(address(c), amount);

        Reverter bad = new Reverter();

        bool ok;
        try c.sendMoney(address(bad), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert in fallback");
    }
    receive() external payable {
        revert("revert in receive");
    }
}
